// Курс «Путь к чтению Корана». Каждый этап добавляет одно новое, как в классических букварях («Каида Нураниййа»):
// буквы по отдельности → формы букв в слове → огласовки (фатха, касра, дамма, сукун, танвин) → слоги → слова →
// слова с маддом, сукуном и шаддой → аяты и особые написания мусхафа; затем махраджи и таджвид по риваяту Хафса
// от Асыма (путь аш-Шатыбии) и чтение сур Джуз Аммы.
// Номера уроков менялись в версии 1.11.0: старый прогресс переводится в store.js (LESSON_MOVES).
//
// Разметка текста: {арабский}, арабская вставка (можно с цветной разметкой [код…]), **жирный**.
// Шаги урока: card | letter | forms | blend | zone | rule | ex (упражнение-генератор) | quiz (вопрос на понимание) | read | speak.
// letter: отдельная буква и её название; forms: та же буква в начале, середине и конце слова; blend: «слог + слог = слово».

const q = (qq, a, why) => ({ t: "quiz", q: qq, a, why });
const ex = (k, n, o = {}) => ({ t: "ex", k, n, ...o });
const card = (title, body, o = {}) => ({ t: "card", title, body, ...o });

