// Последний этап, чтение сур (порядок: от коротких и лёгких к длинным)
export const SURAH_PATH = [1, 112, 113, 114, 108, 103, 110, 111, 106, 105, 107, 109, 102, 101, 104, 97, 95, 94, 93, 99, 100, 92, 91, 90, 98, 96, 89, 88, 87, 86, 85, 84, 83, 82, 81, 80, 79, 78];
export const SURAH_UNIT = { id: 14, hue: "gold", icon: "۞", title: "Читаем Коран", sub: "Аль-Фатиха и Джуз Амма" };

// Буквы, пройденные к уроку (включая его самого): из них складываются слоги и слова в этапе «Алфавит».
export function knownLetters(lessonId) {
  const out = [];
  for (const l of UNITS[1].lessons) {
    if (Array.isArray(l.letters)) out.push(...l.letters);
    if (l.id === lessonId) return [...new Set(out)];
  }
  return null; // после алфавита известны все буквы
}

export const ALL_LESSONS = UNITS.flatMap((u) => u.lessons.map((l) => ({ ...l, unit: u.id })));
export const lessonById = Object.fromEntries(ALL_LESSONS.map((l) => [l.id, l]));
export const unitById = Object.fromEntries([...UNITS, SURAH_UNIT].map((u) => [u.id, u]));
